// 模板导入，投票只用 candidate 和 count。
class Solution {
    public int majorityElement(int[] nums) {
        int candidate = 0;
        int count = 0;
        for (int num : nums) {
            // 票被抵消光后，当前元素重新作为候选。
            if (count == 0) {
                candidate = num;
            }
            count += (num == candidate) ? 1 : -1;
        }
        // 多数元素多到抵消不完，循环结束时它仍是 candidate。
        return candidate;
    }
}

class Solution {
    public int hammingWeight(int n) {
        int count = 0;
        while (n != 0) {
            // n-1 翻转最低的 1 及其右侧，相与后只去掉这一个 1。
            n &= (n - 1);
            count++;
        }
        return count;
    }
}

import java.util.*;
class Solution {
    public boolean isStraight(int[] nums) {
        Arrays.sort(nums);
        int first = 0;
        // 0 是万能牌，先跳过，后面只检查真实牌面。
        while (first < nums.length && nums[first] == 0) {
            first++;
        }
        // 全是大小王，任意顺子都能凑出。
        if (first == nums.length) {
            return true;
        }
        for (int i = first + 1;
        i < nums.length;
        i++) {
            // 非 0 牌重复就无法排成连续顺子。
            if (nums[i] == nums[i - 1]) {
                return false;
            }
        }
        // 最大牌与最小非 0 牌跨度小于 5，缺口不超过 0 的个数。
        return nums[nums.length - 1] - nums[first] < 5;
    }
}

// LC440 原题：1<=k<=n<=1000000000。调用方必须保证有效名次；此题解不检查域外输入。
class Solution {
    public int findKthNumber(int n, int k) {
        int current = 1;
        long remaining = k - 1L;
        // 1 已占字典序第一位，还要再跳过 k-1 个数。
        while (remaining > 0) {
            long steps = countSteps(n, current, current + 1L);
            if (steps <= remaining) {
                // 目标不在这棵前缀子树，整棵跳过。
                current++;
                remaining -= steps;
            } else {
                // 目标在子树内，进入下一层最左孩子并吃掉当前节点。
                current *= 10;
                remaining--;
            }
        }
        return current;
    }
    private long countSteps(int n, long first, long next) {
        long steps = 0;
        while (first <= n) {
            // 本层落在 [first, next) 且不超过 n 的数字个数。
            steps += Math.min((long) n + 1, next) - first;
            first *= 10;
            next *= 10;
        }
        return steps;
    }
}

class Solution {
    public int countDigitOne(int n) {
        long digit = 1, ans = 0;
        // 从个位开始：high 是更高位，cur 是当前位，low 是更低位组成的数
        long high = n / 10, cur = n % 10, low = 0;
        while (high != 0 || cur != 0) {
            if (cur == 0) {
                // 当前位是 0：只有高位更小的数才会在这一位出现 1
                ans += high * digit;
            } else if (cur == 1) {
                // 当前位正好是 1：高位更小的全部计入，高位相等时低位只能取到 low
                ans += high * digit + low + 1;
            } else {
                // 当前位大于 1：高位取到 high 时这一位也已经出现过完整一轮 1
                ans += (high + 1) * digit;
            }
            low += cur * digit;
            cur = high % 10;
            high /= 10;
            digit *= 10;
            // 处理完当前位后，权重进到下一位
        }
        return (int) ans;
    }
}

