        }
    }
}

import java.util.*;
class Solution {
    private final int[] original;
    private final Random random = new Random();
    public Solution(int[] nums) {
        // 保存一份独立副本，避免外部对 nums 的修改影响内部状态。
        this.original = nums.clone();
    }
    public int[] reset() {
        // 返回副本，避免调用方修改 original。
        return original.clone();
    }
    public int[] shuffle() {
        int[] result = original.clone();
        // Fisher-Yates：位置 i 与 [0, i] 中随机下标交换，才能等概率。
        for (int i = result.length - 1;
        i > 0;
        i--) {
            int j = random.nextInt(i + 1);
            int temp = result[i];
            result[i] = result[j];
            result[j] = temp;
        }
        return result;
    }
}

class Solution {
    // 只通过该接口取偏置位，保证不引入别的随机源。
    interface BiasedBitSource {
        int nextBit();
        // 独立返回 0 或 1，P(1)=p。
    }
    private final BiasedBitSource source;
    public Solution(BiasedBitSource source) {
        this.source = source;
    }
    // 01 与 10 等概率，用来抽出一个不偏向的 bit。
    private int fairBit() {
        while (true) {
            int first = source.nextBit();
            int second = source.nextBit();
            // P(01)=(1-p)p 与 P(10) 相同，返回 0 不会偏向某一侧。
            if (first == 0 && second == 1) {
                return 0;
            }
            if (first == 1 && second == 0) {
                return 1;
            }
            // 00、11 的概率一般不等，不能当公平位，丢掉重抽。
        }
    }
    public double nextUniformDouble() {
        long bits = 0L;
        // 选取步长 2^-53 的等距网格，共 2^53 个点；并非枚举所有 double。
        for (int i = 0;
        i < 53;
        i++) {
            bits = (bits << 1) | fairBit();
        }
        // bits 均匀落在 [0, 2^53)，再除以 2^53 就落在 [0,1)。
        return bits / (double) (1L << 53);
    }
}

import java.util.*;
class WeightedPicker {
    private final int[] nums;
    private final double[] prefix;
    private final double total;
    private final Random random = new Random();
    public WeightedPicker(int[] nums, double[] probabilities) {
        if (nums == null || probabilities == null || nums.length != probabilities.length || nums.length == 0) {
            throw new IllegalArgumentException("nums 与 probabilities 长度必须相同且非空");
        }
        this.nums = nums.clone();
        this.prefix = new double[probabilities.length];
        double sum = 0.0;
        // 前缀和把每个元素映射成长度等于其概率的一段。
        for (int i = 0;
        i < probabilities.length;
        i++) {
            if (!Double.isFinite(probabilities[i]) || probabilities[i] < 0.0) {
                throw new IllegalArgumentException("概率不能为负数");
            }
            double next = sum + probabilities[i];
            if (!Double.isFinite(next) || (probabilities[i] > 0 && next == sum)) {
                throw new IllegalArgumentException("权重总和溢出或正权重小到无法形成区间");
            }
            sum = next;
            prefix[i] = sum;
        }
        if (sum <= 0.0) {
            throw new IllegalArgumentException("概率总和必须大于 0");
        }
        this.total = sum;
    }
    public int pick() {
        double r = Math.min(random.nextDouble() * total, Math.nextDown(total));
        // r 属于 [0, total)，用来落在某一段上。
        int left = 0;
        int right = prefix.length - 1;
        // prefix 单调，二分第一个右端点严格大于 r 的区间。
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (prefix[mid] > r) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return nums[left];
    }
}

public class RectangleOverlap {
    static class Rectangle {
        int x1;
        int y1;
        int x2;
        int y2;
        // 左下 (x1,y1)，右上 (x2,y2)
        Rectangle(int x1, int y1, int x2, int y2) {
            if (x1 > x2 || y1 > y2) throw new IllegalArgumentException("ordered corners required");
            this.x1 = x1;
            this.y1 = y1;
            this.x2 = x2;
            this.y2 = y2;
        }
    }
    public boolean isOverlap(Rectangle a, Rectangle b) {
        // 完全在左、右、下、上任一侧（含边贴边）就一定不相交
        boolean separated = Math.min(a.x2, b.x2) <= Math.max(a.x1, b.x1)
        || Math.min(a.y2, b.y2) <= Math.max(a.y1, b.y1);
        return !separated;
    }
}

import java.util.*;
import java.util.random.RandomGenerator;
public final class ReservoirFive<T> {
    private final RandomGenerator random;
    private final List<T> sample=new ArrayList<>(5);
    private long seen;
    public ReservoirFive(RandomGenerator random){
        this.random=Objects.requireNonNull(random);
    }
    public void accept(T value){
        Objects.requireNonNull(value);
        long next=Math.incrementExact(seen);
        if(next<=5)sample.add(value);
        else{
            long j=random.nextLong(next);
            if(j<5)sample.set((int)j,value);
        }
        seen=next;
    }
    public List<T> snapshot(){
        return List.copyOf(sample);
    }
    public long seen(){
        return seen;
    }
    private static void choices(int next,int n,int[] pool,int[] draws,Map<String,Integer> counts){
        if(next>n){
            int[] expected=pool.clone();
            Arrays.sort(expected);
            RandomGenerator scripted=new RandomGenerator(){
                int at;
                public long nextLong(){
                    throw new AssertionError("unexpected unbounded draw");
                }
                public long nextLong(long bound){
                    int draw=draws[at++];
                    if(draw<0||draw>=bound)throw new AssertionError();
                    return draw;
                }
            }
            ;
            ReservoirFive<Integer> actual=new ReservoirFive<>(scripted);
            for(int value=1;value<=n;value++)actual.accept(value);
            int[] a=actual.snapshot().stream().mapToInt(Integer::intValue).sorted().toArray();
            if(!Arrays.equals(a,expected))throw new AssertionError();
            counts.merge(Arrays.toString(a),1,Integer::sum);
            return;
        }
        for(int draw=0;draw<next;draw++){
            int[] a=pool.clone();
            if(draw<5)a[draw]=next;
            draws[next-6]=draw;
            choices(next+1,n,a,draws,counts);
        }
    }
}

class Solution {
    public int reachNumber(int target) {
        long goal = Math.abs((long) target);
        long sum = 0;
        int steps = 0;
        while (sum < goal || ((sum - goal) & 1L) != 0) {
            steps++;
            sum += steps;
        }
        return steps;
    }
}
